#define N3_MOVE_COUNT ((int)(sizeof kN3Moves / sizeof kN3Moves[0]))
static inline int N3MoveFind(uint32_t chr, uint32_t id) {
    for (int i = 0; i < N3_MOVE_COUNT; ++i)
        if (kN3Moves[i].chr == chr && kN3Moves[i].id == id) return i;
    return -1;
}
// Initialization and idle are required by the veto fallback.
static inline int N3MoveProtected(uint32_t id) { return id == 0 || id == 2; }
// user #14655: a move that kills the boss when forced (Yoritomo 0x4E3B > 0x4E3C, "hit reaction / Ki-break motion 304xx": boss HP went 42525 -> 0 at
// once in the 2026-10-20 00:17 log) must never be selectable, alone or inside a sequence.
static inline int N3MoveUnsafe(uint32_t chr, uint32_t id) { return chr == 16102u && (id == 0x4E3Bu || id == 0x4E3Cu); }
// user #14664/#14665: attacks are the primary picks; every other safe motion (twitches, Ki-break poses, steps, reactions) goes in ONE
// "Animations and twitches" group. attack = seen/recorded attack (A / S), game-table attack-family motion, or the 0x4E21 chain start.
static inline int N3MoveAttack(const N3Move* m) {
    return m->kind == 'A' || m->kind == 'S' || (m->label && (strstr(m->label, "attack-family") || strstr(m->label, "chain start")));
}
static inline int N3MoveSelectable(const N3Move* m) { return N3MoveProtected(m->id) || !N3MoveUnsafe(m->chr, m->id); }
// #13786: twitches, combo fragments and movement states are hidden from the move list by default.
static inline int N3MoveTwitch(const N3Move* m) { return m->kind == 'T' || m->kind == 'L' || m->kind == 'M'; }
